import random, sys
from datetime import datetime
from dateutil.relativedelta import relativedelta

random.seed(7)
abs_choices = [None, None, None, 0, 1, 2, 5]
def mk():
    kw = {}
    for name in ["year", "month", "day", "hour", "minute", "second", "microsecond"]:
        v = random.choice(abs_choices)
        if v is not None:
            kw[name] = v
    for name in ["years", "months", "days", "hours", "minutes", "seconds", "microseconds", "leapdays"]:
        if random.random() < 0.4:
            kw[name] = random.randint(-3, 3)
    return relativedelta(**kw)

print("MODULE", sys.modules['dateutil.relativedelta'].__file__)
for i in range(400):
    a, b = mk(), mk()
    try:
        r1 = repr(a + b)
    except Exception as e:
        r1 = "ERR %s" % e
    try:
        r2 = repr(a - b)
    except Exception as e:
        r2 = "ERR %s" % e
    try:
        r3 = repr(datetime(2000, 6, 15, 12, 30, 30) + (a + b))
    except Exception as e:
        r3 = "ERR %s" % e
    print(i, repr(a), "|", repr(b), "=>", r1, "||", r2, "||", r3)
EOF
