import random
from datetime import datetime
from dateutil.relativedelta import relativedelta

random.seed(11)
ABS = ["year", "month", "day", "hour", "minute", "second", "microsecond"]
REL = ["years", "months", "days", "hours", "minutes", "seconds",
       "microseconds", "leapdays"]

def mk():
    kw = {}
    for name in ABS:
        v = random.choice([None, None, 0, 1, 2, 5])
        if v is not None:
            kw[name] = v
    for name in REL:
        if random.random() < 0.4:
            kw[name] = random.randint(-3, 3)
    return relativedelta(**kw)

bad = 0
for i in range(2000):
    a, b = mk(), mk()
    s = a + b
    d = a - b
    for name in ABS:
        av, bv = getattr(a, name), getattr(b, name)
        exp_s = bv if bv is not None else av
        exp_d = av if av is not None else bv
        if getattr(s, name) != exp_s or getattr(d, name) != exp_d:
            bad += 1
            print("MISMATCH", name, repr(a), repr(b), repr(s), repr(d))
            break
    for name in REL:
        if getattr(s, name) != getattr(a, name) + getattr(b, name):
            bad += 1
            print("REL MISMATCH add", name, repr(a), repr(b), repr(s))
            break
        if getattr(d, name) != getattr(a, name) - getattr(b, name):
            bad += 1
            print("REL MISMATCH sub", name, repr(a), repr(b), repr(d))
            break
print("bad =", bad)
EOF
